package com.healthcare.portal.controller;
import com.healthcare.portal.dto.RecoveryRequests.*; import com.healthcare.portal.service.AccountRecoveryService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AccountRecoveryController { private final AccountRecoveryService service; public AccountRecoveryController(AccountRecoveryService s){service=s;} @PostMapping("/forgot-password") public ResponseEntity<?> forgot(@RequestBody EmailRequest r){service.requestReset(r.getEmail()); return ResponseEntity.ok(java.util.Map.of("message","If the account exists, a reset email has been sent."));} @PostMapping("/reset-password") public ResponseEntity<?> reset(@RequestBody ResetRequest r){service.reset(r.getToken(),r.getPassword()); return ResponseEntity.ok(java.util.Map.of("message","Password reset successful"));} @PostMapping("/send-email-otp") public ResponseEntity<?> sendOtp(@RequestBody EmailRequest r){service.sendOtp(r.getEmail()); return ResponseEntity.ok(java.util.Map.of("message","OTP sent"));} @PostMapping("/verify-email-otp") public ResponseEntity<?> verify(@RequestBody OtpRequest r){service.verifyOtp(r.getEmail(),r.getOtp()); return ResponseEntity.ok(java.util.Map.of("message","Email verified"));} }
